    load = 0
    for c in ordered:
        d = demand_of(c)
        if current and load + d > capacity:
            routes.append(current)
            current = [c]
            load = d
        else:
            current.append(c)
            load += d
    if current:
        routes.append(current)

    seen = {}
    repaired = []
    for r in routes:
        nr = []
        for c in r:
            if c not in seen:
                seen[c] = 1
                nr.append(c)
        if nr:
            repaired.append(nr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        dc = demand_of(c)
        for r in repaired:
            route_load = 0
            for x in r:
                route_load += demand_of(x)
            if route_load + dc <= capacity:
                r.append(c)
                placed = True
                break
        if not placed:
            repaired.append([c])

    routes = repaired

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        total = dist(depot_id, route[0])
        for i in range(len(route) - 1):
            total += dist(route[i], route[i + 1])
        total += dist(route[-1], depot_id)
        return total

    improved = []
    for r in routes:
        if len(r) <= 2:
            improved.append(r[:])
            continue

        unvisited = r[:]
        start = unvisited[0]
        bestd = dist(depot_id, start)
        for c in unvisited[1:]:
            dc = dist(depot_id, c)
            if dc < bestd or (dc == bestd and c < start):
                start = c
                bestd = dc
        seq = [start]
        unvisited.remove(start)
        while unvisited:
            last = seq[-1]
            best = unvisited[0]
            bestv = dist(last, best)
            for c in unvisited[1:]:
                dv = dist(last, c)
                if dv < bestv or (dv == bestv and c < best):
                    best = c
                    bestv = dv
            seq.append(best)
            unvisited.remove(best)

        changed = True
        while changed:
            changed = False
            n = len(seq)
            base = route_cost(seq)
            for i in range(n - 1):
                for j in range(i + 1, n):
                    cand = seq[:i] + seq[i:j + 1][::-1] + seq[j + 1:]
                    if route_cost(cand) + 1e-12 < base:
                        seq = cand
                        changed = True
                        break
                if changed:
                    break
        improved.append(seq)

    used = {}
    final_routes = []
    for r in improved:
        nr = []
        load = 0
        for c in r:
            if c in used:
                continue
            d = demand_of(c)
            if load + d <= capacity:
                nr.append(c)
                load += d
                used[c] = 1
        if nr:
            final_routes.append(nr)

    for c in customers:
        if c not in used:
            placed = False
            dc = demand_of(c)
            for r in final_routes:
                if route_load(r) + dc <= capacity:
                    r.append(c)
                    used[c] = 1
                    placed = True
                    break
            if not placed:
                final_routes.append([c])
                used[c] = 1

    return final_routes
